{
  "items": [
    {
      "name": "MvPolynomial.degreeOf_mul_le",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (i : σ) (f g : MvPolynomial σ R),\n  MvPolynomial.degreeOf i (f * g) ≤ MvPolynomial.degreeOf i f + MvPolynomial.degreeOf i g"
    },
    {
      "name": "Matrix.det_matrixOfPolynomials",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Block",
      "kind": "theorem",
      "type": "∀ {R : Type v} [inst : CommRing R] {n : ℕ} (p : Fin n → Polynomial R),\n  (∀ (i : Fin n), (p i).natDegree = ↑i) → (∀ (i : Fin n), (p i).Monic) → (Matrix.of fun i j => (p j).coeff ↑i).det = 1"
    },
    {
      "name": "Matrix.det_le",
      "module_name": "Mathlib.LinearAlgebra.Matrix.AbsoluteValue",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {S : Type u_2} [inst : CommRing R] [Nontrivial R] [inst_2 : CommRing S] [inst_3 : LinearOrder S]\n  [IsStrictOrderedRing S] {n : Type u_3} [inst_5 : Fintype n] [inst_6 : DecidableEq n] {A : Matrix n n R}\n  {abv : AbsoluteValue R S} {x : S},\n  (∀ (i j : n), abv (A i j) ≤ x) → abv A.det ≤ (Fintype.card n).factorial • x ^ Fintype.card n"
    },
    {
      "name": "Matrix.charmatrix_apply_natDegree_le",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Charpoly.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] {n : Type v} [inst_1 : DecidableEq n] [inst_2 : Fintype n] {M : Matrix n n R}\n  (i j : n), (M.charmatrix i j).natDegree ≤ if i = j then 1 else 0"
    },
    {
      "name": "Matrix.det",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Determinant.Basic",
      "kind": "definition",
      "type": "{n : Type u_2} → [DecidableEq n] → [Fintype n] → {R : Type v} → [CommRing R] → Matrix n n R → R"
    },
    {
      "name": "Polynomial.natDegree_prod_le",
      "module_name": "Mathlib.Algebra.Polynomial.BigOperators",
      "kind": "theorem",
      "type": "∀ {R : Type u} {ι : Type w} (s : Finset ι) [inst : CommSemiring R] (f : ι → Polynomial R),\n  (∏ i ∈ s, f i).natDegree ≤ ∑ i ∈ s, (f i).natDegree"
    }
  ]
}
